/** Own app records, not proof of remote execution. Validate the whole result after every edit. */
export function workReferenceErrors(next: WorkState, knownSources: readonly string[]): string[] {
  const tasks = new Map(next.tasks.map(t => [t.id, t]));
  const rooms = new Set(next.rooms.map(r => r.id));
  const sources = new Set(knownSources);
  const errors: string[] = [];
  const entities=[...next.notes,...next.rooms,...next.tasks,...next.command.missions,...next.command.approvals,...next.command.interactions];
  if(new Set(entities.map(e=>e.id)).size!==entities.length)errors.push('Eigene Entitäten benötigen über alle Datenbereiche hinweg eindeutige IDs.');
  if (next.settings.neuro.focusMissionId && !next.command.missions.some(m => m.id === next.settings.neuro.focusMissionId)) errors.push('Die ausgewählte Fokusmission fehlt.');
  for (const r of next.rooms) if (r.sources.some(id => !sources.has(id))) errors.push(`${r.title}: Eine Quelle des Missionraums fehlt.`);
  for (const m of next.command.missions) {
    if (m.taskIds.some(id => !tasks.has(id))) errors.push(`${m.title}: Eine referenzierte Aufgabe fehlt.`);
    if (m.roomId && !rooms.has(m.roomId)) errors.push(`${m.title}: Der referenzierte Missionraum fehlt.`);
    if (m.sourceIds.some(id => !sources.has(id))) errors.push(`${m.title}: Eine ausgewählte Quelle fehlt im Quellenbestand.`);
    if (['Approved', 'Done'].includes(m.stage) && m.taskIds.some(id => tasks.get(id)?.status !== 'Erledigt')) {
      errors.push(`${m.title}: Zugeordnete Aufgaben müssen vor der Abnahme abgeschlossen sein.`);
    }
  }
  return errors;
}

