    if (!old || !equal(old, t)) pending.push({ kind: 'task-updated', entityId: t.id, neuro_context: { taskStatus: t.status, priority: t.priority }, title: `Aufgabe ${old ? 'aktualisiert' : 'angelegt'}: ${t.title} · ${t.status}` });
