  for (const key of Object.keys(labels) as (keyof typeof labels)[]) {
    if (!equal(current[key], next[key])) pending.push({ kind: 'workspace-updated', entityId: null, neuro_context: {}, title: `${labels[key]} aktualisiert` });
  }
  let sequence = current.command.events.at(-1)?.sequence || 0;
  const events: AppEvent[] = pending.map(e => ({ ...e, id: makeId(), sequence: ++sequence, at: now.toISOString(), origin: 'app', neuro_profile: calculateNeuroScore({ kind: e.kind, ...e.neuro_context }) }));
